"""Emit Lean data and ordinary-kernel proofs for the exact finite pipeline.

The JSON file is only an untrusted serialization format.  Every primal and
separator payload is rechecked by a generated Lean proof and packaged as a
``CertifiedMomentRow``.  Large audits are sharded so ``lake build`` can check
them in parallel; no native evaluator is part of the proof chain.
"""

from __future__ import annotations

import argparse
import json
from fractions import Fraction
from pathlib import Path


HEADER = """-- This file is generated by tools/generators/emit_main_pipeline_lean.py.
-- Do not edit it by hand; regenerate it from the exact JSON certificate bundle.
"""


def write_generated(path: Path, lines: list[str]) -> None:
    """Avoid invalidating expensive Lean shards when their bytes did not change."""
    content = "\n".join(lines)
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return
    path.write_text(content, encoding="utf-8", newline="\n")


def rat(text: str | int) -> str:
    text = str(text)
    if "/" in text:
        num, den = text.split("/", 1)
        return f"({num} / {den})"
    return text


def nat_array(values: list[int], width: int = 24) -> str:
    lines = []
    for start in range(0, len(values), width):
        lines.append("  " + ", ".join(map(str, values[start:start + width])))
    return "#[\n" + ",\n".join(lines) + "\n]"


def sparse(values: list[list[object]]) -> str:
    if not values:
        return "[]"
    return "[" + ", ".join(f"({word}, {rat(value)})" for word, value in values) + "]"


def rat_list(values: list[object]) -> str:
    return "[" + ", ".join(rat(value) for value in values) + "]"


def nested_rat_list(rows: list[list[object]]) -> str:
    return "[" + ", ".join(rat_list(row) for row in rows) + "]"


def fraction_lean(value: Fraction) -> str:
    if value.denominator == 1:
        return str(value.numerator)
    return f"({value.numerator} / {value.denominator})"


def inverse_matrix(rows: list[list[object]]) -> list[list[Fraction]]:
    """Exact Gauss--Jordan inversion; failure means a corrupt JSON certificate."""
    n = len(rows)
    if any(len(row) != n for row in rows):
        raise ValueError("inverse witness is not square")
    aug = [
        [Fraction(str(value)) for value in row]
        + [Fraction(int(i == j)) for j in range(n)]
        for i, row in enumerate(rows)
    ]
    for col in range(n):
        pivot = next((i for i in range(col, n) if aug[i][col]), None)
        if pivot is None:
            raise ValueError("singular affine-rank minor in certificate bundle")
        aug[col], aug[pivot] = aug[pivot], aug[col]
        scale = aug[col][col]
        aug[col] = [value / scale for value in aug[col]]
        for i in range(n):
            if i == col:
                continue
            scale = aug[i][col]
            if scale:
                aug[i] = [x - scale * y for x, y in zip(aug[i], aug[col])]
    return [row[n:] for row in aug]


def lower_minor(cert: dict) -> list[list[int]]:
    base = cert["base"]
    return [
        [((word >> coord) & 1) - ((base >> coord) & 1)
         for coord in cert["lower_coords"]]
        for word in cert["lower_points"]
    ]


def normal_minor(cert: dict) -> list[list[object]]:
    return [
        [normal[coord] for coord in cert["normal_coords"]]
        for normal in cert["normals"]
    ]


def inverse_literal(rows: list[list[object]]) -> str:
    inverse = inverse_matrix(rows)
    return "[" + ", ".join(
        "[" + ", ".join(fraction_lean(value) for value in row) + "]"
        for row in inverse) + "]"


def affine_literal(cert: dict) -> str:
    return ("{ rank := %d, base := %d, lowerPoints := %s, lowerCoords := %s, "
            "normals := %s, normalCoords := %s }") % (
        cert["rank"], cert["base"], str(cert["lower_points"]),
        str(cert["lower_coords"]), nested_rat_list(cert["normals"]),
        str(cert["normal_coords"]))


def face_literal(cert: dict) -> str:
    return ("{ active0 := %d, active1 := %d, dual := %s, "
            "relativeInterior := { p0 := %s, p1 := %s } }") % (
        cert["active0"], cert["active1"], rat_list(cert["dual"]),
        sparse(cert["p0"]), sparse(cert["p1"]))


def pair_literal(values: list[int]) -> str:
    q, m, mask0, mask1 = values
    return f"⟨{q}, {m}, {mask0}, {mask1}⟩"


def moment_result_literal(cert: dict) -> str:
    if cert["kind"] == "primal":
        return ".feasible %d { p0 := %s, p1 := %s }" % (
            cert["pair"], sparse(cert["p0"]), sparse(cert["p1"]))
    return ".infeasible %d { h := %s, lower := %s, upper := %s }" % (
        cert["pair"], rat_list(cert["h"]), rat(cert["lower"]),
        rat(cert["upper"]))


def emit_pairs(data: dict, out_dir: Path) -> None:
    lines = [HEADER, "import MainTheory.FinitePipeline", "",
             "namespace MainTheory.Generated.FinitePairData", "",
             "open MainTheory.FinitePipeline", "", "set_option maxRecDepth 1000000", ""]
    lines.append("def pairTable : Array FiberPair := #[")
    for q, m, mask0, mask1 in data["pair_table"]:
        lines.append(f"  ⟨{q}, {m}, {mask0}, {mask1}⟩,")
    lines.extend([
        "]", "",
        "theorem pairTable_size : pairTable.size = 11422 := by decide", "",
        "def coarsePairIds : Array ℕ := " + nat_array(data["coarse_pair_ids"]), "",
        "theorem coarsePairIds_size : coarsePairIds.size = 508 := by decide", "",
        "def compatiblePairIds : Array ℕ := " + nat_array(data["compatible_pair_ids"]), "",
        "theorem compatiblePairIds_size : compatiblePairIds.size = 215 := by decide", "",
        "end MainTheory.Generated.FinitePairData", "",
    ])
    write_generated(out_dir / "FinitePairData.lean", lines)


def emit_moments(data: dict, out_dir: Path) -> None:
    certs = data["moment_certificates"]
    pairs = data["pair_table"]
    shard_size = 8
    shard_names: list[str] = []
    summary_names: list[str] = []

    for shard_start in range(0, len(certs), shard_size):
        shard_no = shard_start // shard_size
        module = f"FiniteMomentDataShard{shard_no:02d}"
        shard_names.append(module)
        namespace = f"MainTheory.Generated.{module}"
        lines = [HEADER, "import MainTheory.Generated.FinitePairData", "",
                 f"namespace {namespace}", "", "open MainTheory.FinitePipeline", "",
                 "set_option maxRecDepth 1000000", "set_option maxHeartbeats 4000000", ""]
        row_names: list[str] = []
        for local, cert in enumerate(certs[shard_start:shard_start + shard_size]):
            idx = shard_start + local
            row = f"row{idx}"
            pair_name = f"pair{idx}"
            result_name = f"result{idx}"
            valid_name = f"result{idx}_valid"
            row_names.append(row)
            pair = pairs[cert["pair"]]
            lines.extend([
                f"def {pair_name} : FiberPair := {pair_literal(pair)}", "",
                f"def {result_name} : MomentResultData := {moment_result_literal(cert)}", "",
                f"theorem {valid_name} : {result_name}.ValidFor {pair_name} := by",
                f"  simp only [{result_name}, MomentResultData.ValidFor]",
            ])
            if cert["kind"] == "primal":
                lines.extend([
                    "  constructor",
                    f"  · norm_num [sparseEntriesValid, {pair_name}, Nat.testBit,",
                    "      Nat.shiftRight_eq_div_pow]",
                    f"  · norm_num [sparseEntriesValid, {pair_name}, Nat.testBit,",
                    "      Nat.shiftRight_eq_div_pow]",
                    "  · norm_num [sparseMass]",
                    "  · norm_num [sparseMass]",
                    "  · intro k",
                    "    fin_cases k <;>",
                    "      norm_num [sparseMoment, wordOfNat, feature, bit, Nat.testBit,",
                    "        Nat.shiftRight_eq_div_pow]",
                ])
            else:
                lines.extend([
                    f"  norm_num [SeparatorData.Valid, {pair_name}, score, listVector21,",
                    "    feature, bit, InMask]",
                    "  constructor",
                    "  · intro x hx",
                    "    fin_cases x <;>",
                    "      norm_num [Nat.testBit, Nat.shiftRight_eq_div_pow] at hx <;>",
                    "      norm_num [Nat.testBit, Nat.shiftRight_eq_div_pow]",
                    "  · intro x hx",
                    "    fin_cases x <;>",
                    "      norm_num [Nat.testBit, Nat.shiftRight_eq_div_pow] at hx <;>",
                    "      norm_num [Nat.testBit, Nat.shiftRight_eq_div_pow]",
                ])
            lines.extend([
                "",
                f"def {row} : CertifiedMomentRow where",
                f"  pairId := {cert['pair']}",
                f"  pair := {pair_name}",
                f"  result := {result_name}",
                f"  result_pairId := by rfl",
                f"  valid := {valid_name}", "",
            ])
        rows_expr = ", ".join(row_names)
        lines.extend([f"def rows : List CertifiedMomentRow := [{rows_expr}]", "",
                      f"end {namespace}", ""])
        write_generated(out_dir / f"{module}.lean", lines)

        summary = f"FiniteMomentSummaryShard{shard_no:02d}"
        summary_names.append(summary)
        summary_namespace = f"MainTheory.Generated.{summary}"
        shard_certs = certs[shard_start:shard_start + shard_size]
        qualified = f"MainTheory.Generated.{module}"
        ids = [cert["pair"] for cert in shard_certs]
        feasible_ids = [cert["pair"] for cert in shard_certs if cert["kind"] == "primal"]
        row_defs = [f"{qualified}.row{i}" for i in range(
            shard_start, shard_start + len(shard_certs))]
        result_defs = [f"{qualified}.result{i}" for i in range(
            shard_start, shard_start + len(shard_certs))]
        summary_lines = [
            HEADER, f"import MainTheory.Generated.{module}", "",
            f"namespace {summary_namespace}", "", "open MainTheory.FinitePipeline", "",
            f"theorem rows_length : {qualified}.rows.length = {len(shard_certs)} := by",
            f"  norm_num [{qualified}.rows]", "",
            "theorem rows_pairIds :",
            f"    {qualified}.rows.map CertifiedMomentRow.pairId = {ids} := by",
            f"  norm_num [{qualified}.rows,",
        ]
        summary_lines.extend(f"    {name}," for name in row_defs)
        summary_lines.extend([
            "  ]", "",
            "theorem feasible_result_pairIds :",
            f"    (({qualified}.rows.map CertifiedMomentRow.result).filter",
            "      MomentResultData.isFeasible).map MomentResultData.pairId =",
            f"      {feasible_ids} := by",
            f"  norm_num [{qualified}.rows,",
        ])
        summary_lines.extend(f"    {name}," for name in row_defs + result_defs)
        summary_lines.extend([
            "    MomentResultData.isFeasible, MomentResultData.pairId]", "",
            "theorem feasible_count :",
            f"    (({qualified}.rows.map CertifiedMomentRow.result).filter",
            f"      MomentResultData.isFeasible).length = {len(feasible_ids)} := by",
            "  have h := congrArg List.length feasible_result_pairIds",
            "  simpa using h", "",
            f"end {summary_namespace}", "",
        ])
        write_generated(out_dir / f"{summary}.lean", summary_lines)

    lines = [HEADER, "import MainTheory.Generated.FinitePairData"]
    lines.extend(f"import MainTheory.Generated.{name}" for name in summary_names)
    lines.extend(["", "namespace MainTheory.Generated.FiniteMomentData", "",
                  "open MainTheory.FinitePipeline", "open FinitePairData", "",
                  "set_option maxRecDepth 1000000", ""])
    qualified_rows = [f"MainTheory.Generated.{name}.rows" for name in shard_names]
    qualified_summaries = [f"MainTheory.Generated.{name}" for name in summary_names]
    lines.append("def certifiedRows : List CertifiedMomentRow :=")
    lines.append("  " + " ++\n  ".join(qualified_rows))
    lines.extend([
        "", "def momentResults : Array MomentResultData :=",
        "  (certifiedRows.map CertifiedMomentRow.result).toArray", "",
        "def momentPairs : Array FiberPair :=",
        "  (certifiedRows.map CertifiedMomentRow.pair).toArray", "",
        "def momentPairIds : Array ℕ :=",
        "  (certifiedRows.map CertifiedMomentRow.pairId).toArray", "",
        "theorem certifiedRows_length : certifiedRows.length = 508 := by",
        "  simp only [certifiedRows, List.length_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"  rw [{name}.rows_length]")
    lines.extend([
        "",
        "theorem momentResults_size : momentResults.size = 508 := by",
        "  simp [momentResults, certifiedRows_length]", "",
        "theorem momentResults_pairIds : momentPairIds = coarsePairIds := by",
        "  have h : certifiedRows.map CertifiedMomentRow.pairId = coarsePairIds.toList := by",
        "    simp only [certifiedRows, List.map_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"    rw [{name}.rows_pairIds]")
    lines.extend([
        "    norm_num [coarsePairIds]",
        "  simpa [momentPairIds] using congrArg List.toArray h", "",
        "theorem moment_feasible_count :",
        "    (momentResults.toList.filter (·.isFeasible)).length = 291 := by",
        "  change ((certifiedRows.map CertifiedMomentRow.result).filter",
        "    MomentResultData.isFeasible).length = 291",
        "  simp only [certifiedRows, List.map_append, List.filter_append, List.length_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"  rw [{name}.feasible_count]")
    lines.extend([
        "",
        "def feasiblePairIds : List ℕ :=",
        f"  {[cert['pair'] for cert in certs if cert['kind'] == 'primal']}", "",
        "theorem moment_feasible_result_pairIds :",
        "    ((momentResults.toList.filter MomentResultData.isFeasible).map",
        "      MomentResultData.pairId) = feasiblePairIds := by",
        "  change (((certifiedRows.map CertifiedMomentRow.result).filter",
        "    MomentResultData.isFeasible).map MomentResultData.pairId) = feasiblePairIds",
        "  simp only [certifiedRows, List.map_append, List.filter_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"  rw [{name}.feasible_result_pairIds]")
    lines.extend([
        "  norm_num [feasiblePairIds]", "",
        "/-- Every one of the 508 rows carries a kernel-checked exact primal or",
        "strict-separator proof. -/", 
        "theorem every_certified_row_sound (row : CertifiedMomentRow) :",
        "    if row.result.isFeasible then",
        "      ∃ p0 p1, Feasible row.pair p0 p1",
        "    else ¬ ∃ p0 p1, Feasible row.pair p0 p1 := row.sound", "",
        "end MainTheory.Generated.FiniteMomentData", "",
    ])
    write_generated(out_dir / "FiniteMomentData.lean", lines)


def emit_rank_aggregate(data: dict, out_dir: Path, certs: list[dict],
                        shard_names: list[str], summary_names: list[str]) -> None:
    """Emit only small rewrites over per-shard summary theorems."""
    lines = [HEADER, "import MainTheory.Generated.FiniteMomentData"]
    lines.extend(f"import MainTheory.Generated.{name}" for name in summary_names)
    lines.extend(["", "namespace MainTheory.Generated.FiniteRankData", "",
                  "open MainTheory.FinitePipeline", "open MainTheory.FiniteRankPipeline", "",
                  "set_option maxRecDepth 1000000", ""])
    qualified_rows = [f"MainTheory.Generated.{name}.rows" for name in shard_names]
    qualified_summaries = [f"MainTheory.Generated.{name}" for name in summary_names]
    lines.extend([
        "def certifiedRows : List CertifiedRankRow :=",
        "  " + " ++\n  ".join(qualified_rows), "",
        "def rankRows : Array RankRow :=",
        "  (certifiedRows.map CertifiedRankRow.row).toArray", "",
        "def rankPairIds : Array ℕ :=",
        "  (certifiedRows.map (fun cert => cert.row.pairId)).toArray", "",
        "def compatibleRows : List RankRow :=",
        "  (certifiedRows.map CertifiedRankRow.row).filter (fun row => row.compatible)", "",
        "def rankCompatiblePairIds : Array ℕ :=",
        "  (compatibleRows.map RankRow.pairId).toArray", "",
        "theorem certifiedRows_length : certifiedRows.length = 291 := by",
        "  simp only [certifiedRows, List.length_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"  rw [{name}.rows_length]")
    lines.extend([
        # The rw chain closes this goal on its own; a trailing `norm_num` is
        # reported by Lean as never executed.
        "",
        "theorem rankRows_size : rankRows.size = 291 := by",
        "  simp [rankRows, certifiedRows_length]", "",
        "theorem rankPairIds_expected :",
        "    rankPairIds = FiniteMomentData.feasiblePairIds.toArray := by",
        "  have h : certifiedRows.map (fun cert => cert.row.pairId) =",
        "      FiniteMomentData.feasiblePairIds := by",
        "    simp only [certifiedRows, List.map_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"    rw [{name}.rows_pairIds]")
    lines.extend([
        "    rfl",
        "  simpa [rankPairIds] using congrArg List.toArray h", "",
        # `moment_feasible_result_pairIds` is stated about
        # `momentResults.toList.filter MomentResultData.isFeasible`.  Dropping
        # the `.toList` left the `·` binder's type undetermined, and with
        # `autoImplicit` on that elaborated to nonsense rather than an error.
        "theorem rankPairIds_eq_compatible_source :",
        "    rankPairIds =",
        "      ((FiniteMomentData.momentResults.toList.filter",
        "        MomentResultData.isFeasible).map MomentResultData.pairId).toArray := by",
        "  rw [rankPairIds_expected]",
        "  exact (congrArg List.toArray",
        "    FiniteMomentData.moment_feasible_result_pairIds).symm", "",
        "theorem rank_compatible_count :",
        "    (rankRows.toList.filter (fun row => row.compatible)).length = 215 := by",
        "  change compatibleRows.length = 215",
        "  simp only [compatibleRows, certifiedRows, List.map_append,",
        "    List.filter_append, List.length_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"  rw [{name}.compatible_count]")
    lines.extend([
        "",
        "theorem rankCompatiblePairIds_eq_manifest :",
        "    rankCompatiblePairIds = FinitePairData.compatiblePairIds := by",
        "  have h : compatibleRows.map RankRow.pairId =",
        "      FinitePairData.compatiblePairIds.toList := by",
        "    simp only [compatibleRows, certifiedRows, List.map_append, List.filter_append]",
    ])
    for name in qualified_summaries:
        lines.append(f"    rw [{name}.compatible_pairIds]")
    lines.extend([
        "    rfl",
        "  simpa [rankCompatiblePairIds] using congrArg List.toArray h", "",
        "/-- Every retained row has exact active masks, exact rational affine ranks,",
        "and an exact compatibility flag. -/",
        "theorem every_certified_row_sound (row : CertifiedRankRow) : row.row.Sound := row.sound", "",
        "end MainTheory.Generated.FiniteRankData", "",
    ])
    write_generated(out_dir / "FiniteRankData.lean", lines)


def emit_ranks(data: dict, out_dir: Path) -> None:
    certs = data["rank_certificates"]
    pairs = data["pair_table"]
    # One active-face row per module keeps the peak elaboration memory bounded.
    # The two affine-rank certificates in a row are already substantial.
    shard_size = 1
    shard_names: list[str] = []
    summary_names: list[str] = []

    def append_affine_proof(lines: list[str], theorem_name: str, data_name: str,
                            face_name: str, mask_field: str, cert: dict,
                            mask_words: list[int]) -> None:
        lower_inverse = inverse_literal(lower_minor(cert))
        upper_inverse = inverse_literal(normal_minor(cert))
        lines.extend([
            f"theorem {theorem_name} : {data_name}.Valid {face_name}.{mask_field} := by",
            "  apply AffineRankCertificate.Data.valid_of_inverse_list_witnesses",
            "  · refine",
            f"      {{ inverseRows := {lower_inverse}",
            f"        rank_le := by norm_num [{data_name}]",
            f"        base_lt := by norm_num [{data_name}]",
            "        base_mem := by",
            f"          norm_num [{data_name}, {face_name}, AffineRankCertificate.Data.baseWord,",
            "            AffineRankCertificate.wordOfNat, InMask, Nat.testBit,",
            "            Nat.shiftRight_eq_div_pow]",
            f"        lower_length := by norm_num [{data_name}]",
            f"        coord_length := by norm_num [{data_name}]",
            "        lower_lt := by",
            "          intro i",
            f"          fin_cases i <;> norm_num [{data_name}]",
            "        lower_mem := by",
            "          intro i",
            "          fin_cases i <;>",
            f"            norm_num [{data_name}, {face_name}, AffineRankCertificate.Data.lowerWord,",
            "              AffineRankCertificate.wordOfNat, InMask, Nat.testBit,",
            "              Nat.shiftRight_eq_div_pow]",
            "        coord_lt := by",
            "          intro j",
            "          fin_cases j <;>",
            f"            norm_num [{data_name}, AffineRankCertificate.Data.lowerCoord,",
            "              AffineRankCertificate.coordOfNat]",
            "        right_inverse := by",
            "          ext i j",
            "          fin_cases i <;> fin_cases j <;>",
            f"            simp [{data_name}, Matrix.mul_apply, Fin.sum_univ_succ,",
            "              AffineRankCertificate.Data.lowerMinor,",
            "              AffineRankCertificate.Data.lowerDiff,",
            "              AffineRankCertificate.Data.basePoint,",
            "              AffineRankCertificate.Data.baseWord,",
            "              AffineRankCertificate.Data.lowerWord,",
            "              AffineRankCertificate.Data.lowerCoord, AffineRankCertificate.point,",
            "              AffineRankCertificate.wordOfNat, AffineRankCertificate.coordOfNat,",
            "              bit, Nat.testBit, Nat.shiftRight_eq_div_pow,",
            "              AffineRankCertificate.listMatrix] <;>",
            "            norm_num }",
            "  · refine",
            f"      {{ inverseRows := {upper_inverse}",
            f"        words := {mask_words}",
            "        mask_eq := by decide",
            "        words_lt := by norm_num",
            f"        rank_le := by norm_num [{data_name}]",
            f"        normals_length := by norm_num [{data_name}]",
            "        normal_width := by",
        ])
        codim = 6 - cert["rank"]
        word_cases = " | ".join("rfl" for _ in mask_words)
        if codim == 0:
            lines.extend([
                "          intro i; exact Fin.elim0 i",
                f"        coord_length := by norm_num [{data_name}]",
                "        coord_lt := by",
                "          intro j; exact Fin.elim0 j",
                "        right_inverse := by",
            ])
            lines.append("          ext i; exact Fin.elim0 i")
        else:
            lines.extend([
                "          intro i",
                f"          fin_cases i <;> norm_num [{data_name}]",
                f"        coord_length := by norm_num [{data_name}]",
                "        coord_lt := by",
                "          intro j",
                f"          fin_cases j <;> norm_num [{data_name},",
                "            AffineRankCertificate.Data.normalCoord,",
                "            AffineRankCertificate.coordOfNat]",
                "        right_inverse := by",
                "          ext i j",
                "          fin_cases i",
                "          all_goals fin_cases j",
                f"          all_goals simp [{data_name}, Matrix.mul_apply, Fin.sum_univ_succ,",
                "              AffineRankCertificate.Data.normalMinor,",
                "              AffineRankCertificate.Data.normalFunctional,",
                "              AffineRankCertificate.Data.normalVec,",
                "              AffineRankCertificate.Data.normalCoord,",
                "              AffineRankCertificate.stdBasisVec, AffineRankCertificate.dot,",
                "              AffineRankCertificate.coordOfNat,",
                "              AffineRankCertificate.listMatrix]",
            ])
        lines.extend([
                "        annihilates := by",
                "          intro w hw i",
        ])
        if codim == 0:
            lines.append("          exact Fin.elim0 i")
        else:
            lines.extend([
                "          simp only [List.mem_cons, List.not_mem_nil, or_false] at hw",
                f"          rcases hw with {word_cases}",
                "          all_goals fin_cases i",
                f"          all_goals simp [{data_name}, Fin.sum_univ_succ,",
                "              AffineRankCertificate.Data.normalFunctional,",
                "              AffineRankCertificate.Data.normalVec,",
                "              AffineRankCertificate.Data.basePoint,",
                "              AffineRankCertificate.Data.baseWord, AffineRankCertificate.point,",
                "              AffineRankCertificate.wordOfNat, AffineRankCertificate.dot, bit,",
                "              Nat.testBit, Nat.shiftRight_eq_div_pow]",
            ])
        lines.extend(["      }", ""])

    for shard_start in range(0, len(certs), shard_size):
        shard_no = shard_start // shard_size
        module = f"FiniteRankDataShard{shard_no:02d}"
        shard_names.append(module)
        namespace = f"MainTheory.Generated.{module}"
        lines = [HEADER, "import MainTheory.CompactFaceCertificate", "",
                 f"namespace {namespace}", "", "open MainTheory.FinitePipeline",
                 "open MainTheory.FiniteRankPipeline", "",
                 "set_option maxRecDepth 1000000", "set_option maxHeartbeats 8000000",
                 "set_option linter.unnecessarySeqFocus false", ""]
        row_names: list[str] = []
        for local, cert in enumerate(certs[shard_start:shard_start + shard_size]):
            idx = shard_start + local
            pair_name = f"pair{idx}"
            face_name = f"face{idx}"
            rank0_name = f"rank0_{idx}"
            rank1_name = f"rank1_{idx}"
            raw_name = f"rawRow{idx}"
            row_name = f"row{idx}"
            row_names.append(row_name)
            lines.extend([
                f"def {pair_name} : FiberPair := {pair_literal(pairs[cert['pair']])}", "",
                f"def {face_name} : FaceData := {face_literal(cert)}", "",
                f"def {rank0_name} : AffineRankCertificate.Data := {affine_literal(cert['rank0'])}", "",
                f"def {rank1_name} : AffineRankCertificate.Data := {affine_literal(cert['rank1'])}", "",
            ])
            pair_values = pairs[cert["pair"]]
            full_fiber_zero = (
                cert["active0"] == pair_values[2]
                and cert["active1"] == pair_values[3]
                and all(Fraction(str(value)) == 0 for value in cert["dual"])
            )
            if full_fiber_zero:
                lines.extend([
                f"theorem face{idx}_valid : {face_name}.Valid {pair_name} := by",
                "  apply CompactFaceCertificate.valid_of_fullFiberZeroWitness",
                "  refine",
                "    { primal_valid := ?_",
                f"      positive0 := by norm_num [CompactFaceCertificate.SparsePositive, {face_name}]",
                f"      positive1 := by norm_num [CompactFaceCertificate.SparsePositive, {face_name}]",
                f"      active0_support := by decide",
                f"      active1_support := by decide",
                f"      active0_full := by norm_num [{face_name}, {pair_name}]",
                f"      active1_full := by norm_num [{face_name}, {pair_name}]",
                f"      dual_zero := by decide }}",
                "  refine ⟨?_, ?_, ?_, ?_, ?_⟩",
                f"  · norm_num [sparseEntriesValid, {pair_name}, {face_name}, Nat.testBit,",
                "      Nat.shiftRight_eq_div_pow]",
                f"  · norm_num [sparseEntriesValid, {pair_name}, {face_name}, Nat.testBit,",
                "      Nat.shiftRight_eq_div_pow]",
                f"  · norm_num [sparseMass, {face_name}]",
                f"  · norm_num [sparseMass, {face_name}]",
                "  · intro k",
                "    fin_cases k <;>",
                f"      norm_num [sparseMoment, {face_name}, wordOfNat, feature, bit, Nat.testBit,",
                "        Nat.shiftRight_eq_div_pow]",
                "",
                ])
            else:
                words0 = [w for w in range(64) if (pair_values[2] >> w) & 1]
                words1 = [w for w in range(64) if (pair_values[3] >> w) & 1]
                cases0 = " | ".join("rfl" for _ in words0)
                cases1 = " | ".join("rfl" for _ in words1)
                lines.extend([
                f"theorem face{idx}_valid : {face_name}.Valid {pair_name} := by",
                "  apply CompactFaceCertificate.valid_of_witness",
                "  refine",
                f"    {{ dual_length := by norm_num [{face_name}]",
                "      primal_valid := ?_",
                f"      positive0 := by norm_num [CompactFaceCertificate.SparsePositive, {face_name}]",
                f"      positive1 := by norm_num [CompactFaceCertificate.SparsePositive, {face_name}]",
                "      active0_eq := by decide",
                "      active1_eq := by decide",
                f"      rhs_zero := by norm_num [{face_name}, listFaceDual]",
                "      side0 := ?_",
                "      side1 := ?_ }",
                "  · refine ⟨?_, ?_, ?_, ?_, ?_⟩",
                f"    · norm_num [sparseEntriesValid, {pair_name}, {face_name}, Nat.testBit,",
                "        Nat.shiftRight_eq_div_pow]",
                f"    · norm_num [sparseEntriesValid, {pair_name}, {face_name}, Nat.testBit,",
                "        Nat.shiftRight_eq_div_pow]",
                f"    · norm_num [sparseMass, {face_name}]",
                f"    · norm_num [sparseMass, {face_name}]",
                "    · intro k",
                "      fin_cases k <;>",
                f"        norm_num [sparseMoment, {face_name}, wordOfNat, feature, bit, Nat.testBit,",
                "          Nat.shiftRight_eq_div_pow]",
                "  · refine",
                f"      {{ words := {words0}",
                "        mask_eq := by decide",
                "        words_lt := by norm_num",
                "        sign := ?_ }",
                "    intro w hw",
                "    simp only [List.mem_cons, List.not_mem_nil, or_false] at hw",
                f"    rcases hw with {cases0}",
                f"    all_goals norm_num [{face_name}, listFaceDual, FaceDual.leftCoeff, score,",
                "      feature, bit, wordOfNat, Nat.testBit, Nat.shiftRight_eq_div_pow]",
                "  · refine",
                f"      {{ words := {words1}",
                "        mask_eq := by decide",
                "        words_lt := by norm_num",
                "        sign := ?_ }",
                "    intro w hw",
                "    simp only [List.mem_cons, List.not_mem_nil, or_false] at hw",
                f"    rcases hw with {cases1}",
                f"    all_goals norm_num [{face_name}, listFaceDual, FaceDual.rightCoeff, score,",
                "      feature, bit, wordOfNat, Nat.testBit, Nat.shiftRight_eq_div_pow]",
                "",
            ])
            active_words0 = [w for w in range(64) if (cert["active0"] >> w) & 1]
            active_words1 = [w for w in range(64) if (cert["active1"] >> w) & 1]
            append_affine_proof(lines, f"rank0_{idx}_valid", rank0_name,
                                face_name, "active0", cert["rank0"], active_words0)
            append_affine_proof(lines, f"rank1_{idx}_valid", rank1_name,
                                face_name, "active1", cert["rank1"], active_words1)
            lines.extend([
                f"def {raw_name} : RankRow where",
                f"  pairId := {cert['pair']}",
                f"  pair := {pair_name}",
                f"  face := {face_name}",
                f"  rank0 := {rank0_name}",
                f"  rank1 := {rank1_name}",
                f"  compatible := {str(cert['compatible']).lower()}", "",
                f"theorem {raw_name}_valid : {raw_name}.Valid := by",
                "  refine",
                f"    {{ face_valid := face{idx}_valid",
                f"      rank0_valid := rank0_{idx}_valid",
                f"      rank1_valid := rank1_{idx}_valid",
                f"      rank0_in_range := by norm_num [{raw_name}, {rank0_name}]",
                f"      rank1_in_range := by norm_num [{raw_name}, {rank1_name}]",
                f"      q_lower := by norm_num [{raw_name}, {pair_name}]",
                f"      q_upper := by norm_num [{raw_name}, {pair_name}]",
                f"      m_lower := by norm_num [{raw_name}, {pair_name}]",
                f"      m_dvd_q := by norm_num [{raw_name}, {pair_name}]",
                "      compatible_exact := by",
                f"        norm_num [{raw_name}, {pair_name}, {rank0_name}, {rank1_name},",
                "          RankRow.CompatibilityCondition, RankRow.commonRank] }", "",
                f"def {row_name} : CertifiedRankRow where",
                f"  row := {raw_name}",
                f"  valid := {raw_name}_valid", "",
            ])
        lines.extend([f"def rows : List CertifiedRankRow := [{', '.join(row_names)}]", "",
                      f"end {namespace}", ""])
        write_generated(out_dir / f"{module}.lean", lines)

        summary = f"FiniteRankSummaryShard{shard_no:02d}"
        summary_names.append(summary)
        summary_namespace = f"MainTheory.Generated.{summary}"
        shard_certs = certs[shard_start:shard_start + shard_size]
        qualified = f"MainTheory.Generated.{module}"
        ids = [cert["pair"] for cert in shard_certs]
        compatible_ids = [cert["pair"] for cert in shard_certs if cert["compatible"]]
        row_defs = [f"{qualified}.row{i}" for i in range(
            shard_start, shard_start + len(shard_certs))]
        raw_defs = [f"{qualified}.rawRow{i}" for i in range(
            shard_start, shard_start + len(shard_certs))]
        summary_lines = [
            HEADER, f"import MainTheory.Generated.{module}", "",
            f"namespace {summary_namespace}", "", "open MainTheory.FiniteRankPipeline", "",
            f"theorem rows_length : {qualified}.rows.length = {len(shard_certs)} := by",
            f"  norm_num [{qualified}.rows]", "",
            "theorem rows_pairIds :",
            f"    {qualified}.rows.map (fun cert => cert.row.pairId) = {ids} := by",
            f"  norm_num [{qualified}.rows,",
        ]
        summary_lines.extend(f"    {name}," for name in row_defs + raw_defs)
        summary_lines.extend([
            "  ]", "",
            "theorem compatible_pairIds :",
            f"    (({qualified}.rows.map CertifiedRankRow.row).filter",
            "      (fun row => row.compatible)).map RankRow.pairId =",
            f"      {compatible_ids} := by",
            f"  norm_num [{qualified}.rows,",
        ])
        summary_lines.extend(f"    {name}," for name in row_defs + raw_defs)
        summary_lines.extend([
            "  ]", "",
            "theorem compatible_count :",
            f"    (({qualified}.rows.map CertifiedRankRow.row).filter",
            f"      (fun row => row.compatible)).length = {len(compatible_ids)} := by",
            "  have h := congrArg List.length compatible_pairIds",
            "  simpa using h", "",
            f"end {summary_namespace}", "",
        ])
        write_generated(out_dir / f"{summary}.lean", summary_lines)

    emit_rank_aggregate(data, out_dir, certs, shard_names, summary_names)
    return

    lines = [HEADER, "import MainTheory.Generated.FiniteMomentData"]
    lines.extend(f"import MainTheory.Generated.{name}" for name in shard_names)
    lines.extend(["", "namespace MainTheory.Generated.FiniteRankData", "",
                  "open MainTheory.FinitePipeline", "open MainTheory.FiniteRankPipeline", "",
                  "set_option maxRecDepth 1000000", ""])
    qualified_rows = [f"MainTheory.Generated.{name}.rows" for name in shard_names]
    qualified_row_defs = [
        f"MainTheory.Generated.{shard_names[i // shard_size]}.row{i}"
        for i in range(len(certs))]
    qualified_raw_defs = [
        f"MainTheory.Generated.{shard_names[i // shard_size]}.rawRow{i}"
        for i in range(len(certs))]
    lines.extend([
        "def certifiedRows : List CertifiedRankRow :=",
        "  " + " ++\n  ".join(qualified_rows), "",
        "def rankRows : Array RankRow :=",
        "  (certifiedRows.map CertifiedRankRow.row).toArray", "",
        "def rankPairIds : Array ℕ := rankRows.map RankRow.pairId", "",
        "theorem certifiedRows_length : certifiedRows.length = 291 := by decide", "",
        "theorem rankRows_size : rankRows.size = 291 := by decide", "",
        "theorem rankPairIds_eq_compatible_source :",
        "    rankPairIds = FiniteMomentData.momentResults.filter (·.isFeasible) |>.map (·.pairId) := by",
        "  norm_num [rankPairIds, rankRows, certifiedRows,",
    ])
    for name in qualified_rows + qualified_row_defs + qualified_raw_defs:
        lines.append(f"    {name},")
    lines.extend([
        "    FiniteMomentData.momentResults, FiniteMomentData.certifiedRows,",
        "    MomentResultData.isFeasible, MomentResultData.pairId]", "",
        "theorem rank_compatible_count :",
        "    (rankRows.toList.filter (fun r => r.compatible)).length = 215 := by",
        "  norm_num [rankRows, certifiedRows,",
    ])
    for name in qualified_rows + qualified_row_defs + qualified_raw_defs:
        lines.append(f"    {name},")
    lines.extend([
        "    ]", "",
        "/-- Every retained rank row has exact active masks, exact rational affine ranks,",
        "and an exact compatibility flag. -/",
        "theorem every_certified_row_sound (row : CertifiedRankRow) : row.row.Sound := row.sound", "",
        "end MainTheory.Generated.FiniteRankData", "",
    ])
    write_generated(out_dir / "FiniteRankData.lean", lines)


def emit_orbits(data: dict, out_dir: Path) -> None:
    lines = [HEADER, "import MainTheory.Generated.FiniteRankData", "",
             "namespace MainTheory.Generated.FiniteOrbitData", "",
             "open MainTheory.FinitePipeline", "", "set_option maxRecDepth 1000000", ""]
    lines.append("structure OrbitKey where\n  m : ℕ\n  mask0 : ℕ\n  mask1 : ℕ\n  deriving DecidableEq, Repr, Ord\n")
    lines.append("def orbitKeys : Array OrbitKey := #[")
    for m, mask0, mask1 in data["orbit_keys"]:
        lines.append(f"  ⟨{m}, {mask0}, {mask1}⟩,")
    lines.extend([
        "]", "",
        "theorem orbitKeys_size : orbitKeys.size = 66 := by decide", "",
        "structure CubeWitnessData where",
        "  pairId : ℕ", "  orbitId : ℕ", "  permutationIndex : ℕ",
        "  shift : ℕ", "  swap : Bool", "  deriving Repr", "",
        "def cubeWitnesses : Array CubeWitnessData := #[",
    ])
    for cert in data["cube_witnesses"]:
        lines.append("  ⟨%d, %d, %d, %d, %s⟩," %
                     (cert["pair"], cert["orbit"], cert["perm"], cert["shift"],
                      str(cert["swap"]).lower()))
    lines.extend([
        "]", "",
        "theorem cubeWitnesses_size : cubeWitnesses.size = 215 := by decide", "",
        "end MainTheory.Generated.FiniteOrbitData", "",
    ])
    write_generated(out_dir / "FiniteOrbitData.lean", lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("json")
    parser.add_argument("output_dir")
    args = parser.parse_args()
    data = json.loads(Path(args.json).read_text(encoding="utf-8"))
    out_dir = Path(args.output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    emit_pairs(data, out_dir)
    emit_moments(data, out_dir)
    emit_ranks(data, out_dir)
    emit_orbits(data, out_dir)


if __name__ == "__main__":
    main()
